const safeInt=(v,f=0)=>{const n=Number(v);return Number.isFinite(n)?Math.max(0,Math.floor(n)):f;};
const safeSignedInt=(v,f=0)=>{const n=Number(v);return Number.isFinite(n)?Math.floor(n):f;};
