function playSoundElement(audioElement,volume=.45){if(!audioElement||!isSoundEnabled())return;try{audioElement.currentTime=0;audioElement.volume=volume;const playPromise=audioElement.play();if(playPromise&&typeof playPromise.catch==="function"){playPromise.catch((error)=>{console.warn("効果音を再生できませんでした:",error);});}}catch(error){console.warn("効果音を再生できませんでした:",error);}}
