function resolveEventEffectsText(eventDef,applyResult){if(Array.isArray(applyResult?.effects)&&applyResult.effects.length)return applyResult.effects;return Array.isArray(eventDef.effectsText)?eventDef.effectsText:[];}
function renderEventEffects(eventResult){const effects=Array.isArray(eventResult?.effects)?eventResult.effects:[];if(!dom.eventModalEffects)return;dom.eventModalEffects.innerHTML=`<div class="event-effects"><strong>効果:</strong><ul>${(effects.length?effects:["特に変化はありません"]).map((effect)=>`<li>${effect}</li>`).join("")}</ul></div>`;}
function showDailyEventModal(eventResult){if(!dom.eventModal||!eventResult)return;dom.eventModalTitle.textContent=eventResult.title||"森のできごと";dom.eventModalDescription.textContent=eventResult.description||"";renderEventEffects(eventResult);dom.eventModal.hidden=false;}
function closeDailyEventModal(){if(dom.eventModal)dom.eventModal.hidden=true;}
function queueDailyEventModal(eventResult){showDailyEventModal(eventResult);} 
function previewDailyEventCandidates(s=loadForestLifeState()){const candidates=DAILY_EVENTS.filter((e)=>s.day>=safeInt(e.unlockDay,DAILY_EVENT_START_DAY)&&(!e.condition||e.condition(s)));console.debug("[DailyEvent] candidates",{day:s.day,candidates:candidates.map((e)=>e.id)});return candidates.map((e)=>e.id);} 
function forceDailyEvent(eventId,s=loadForestLifeState()){const ev=DAILY_EVENTS.find((e)=>e.id===eventId);if(!ev)return null;const applyResult=ev.apply(s)||{};const effects=resolveEventEffectsText(ev,applyResult);const eventResult={id:ev.id,title:ev.title,description:ev.description,effects};s.lastDailyEventDay=s.day;pushEventLog(s,{day:s.day,title:ev.title,description:ev.description,effects});queueDailyEventModal(eventResult);saveForestLifeState(s);renderForestLife();return eventResult;}
function applyDailyEvent(s){if(s.day<DAILY_EVENT_START_DAY||s.lastDailyEventDay===s.day)return null;const roll=Math.random();if(roll>DAILY_EVENT_CHANCE){if(DEBUG_DAILY_EVENT)console.debug("[DailyEvent] skipped",{day:s.day,roll});return null;}const candidates=DAILY_EVENTS.filter((e)=>s.day>=safeInt(e.unlockDay,DAILY_EVENT_START_DAY)&&(!e.condition||e.condition(s)));const ev=pickWeightedEvent(candidates);if(DEBUG_DAILY_EVENT)console.debug("[DailyEvent] check",{day:s.day,chance:DAILY_EVENT_CHANCE,roll,candidates:candidates.map((e)=>e.id),selected:ev?.id});if(!ev)return null;const applyResult=ev.apply(s)||{};const effects=resolveEventEffectsText(ev,applyResult);const eventResult={id:ev.id,title:ev.title,description:ev.description,effects};s.lastDailyEventDay=s.day;appendLog(s,`森のできごと: ${ev.description}`);pushEventLog(s,{day:s.day,title:ev.title,description:ev.description,effects});queueDailyEventModal(eventResult);return eventResult;}
window.forceDailyEvent=forceDailyEvent;window.previewDailyEventCandidates=previewDailyEventCandidates;
function getEffectiveReceivableDefaultChance(item,s){const base=BASE_RECEIVABLE_DEFAULT[item.riskLevel]||0.12;return clampRate(base+s.forestUnease*0.012-s.blackMarketTrust*0.002+safeNumber(s.temporaryEffects?.blackMarketDefaultBonusToday,0),0.05,RECEIVABLE_DEFAULT_CAP[item.riskLevel]||0.8);} 
function getEffectivePayableEscapeChance(_,s){return clampRate(0.25+s.forestUnease*0.01-s.blackMarketTrust*0.002,0.05,0.5);} 
function applyAccountsReceivable(s){s.accountsReceivable=s.accountsReceivable.filter((r)=>{if(r.dueDay>s.day)return true;const item=itemById(r.itemId)||{label:r.label,riskLevel:1};if(Math.random()<getEffectiveReceivableDefaultChance(item,s)){s.blackMarketTrust=clamp(s.blackMarketTrust-safeInt(item.trustLossOnDefault,2),0,100);s.forestUnease+=1;appendLog(s,`${item.label}の売掛は、朝になっても届きませんでした。`);}else{changeHand(s,safeInt(r.amount,0));s.blackMarketTrust=clamp(s.blackMarketTrust+1,0,100);appendLog(s,`売掛の約束どおり、${item.label}の代金${r.amount}枚が届きました。`);}return false;});}
function applyAccountsPayable(s){s.accountsPayable=s.accountsPayable.filter((p)=>{if(p.dueDay>s.day)return true;if(s.hand>=p.amount){changeHand(s,-safeInt(p.amount,0));s.blackMarketTrust=clamp(s.blackMarketTrust+1,0,100);appendLog(s,`買掛の支払いとして${p.amount}枚を渡しました。`);return false;}if(Math.random()<getEffectivePayableEscapeChance(p,s)){s.blackMarketTrust=clamp(s.blackMarketTrust-1,0,100);s.forestUnease+=1;appendLog(s,"買掛の帳面は、なぜか白紙になっていました。");return false;}p.amount+=safeInt(p.interestOnFailure,2);p.dueDay+=2;s.blackMarketTrust=clamp(s.blackMarketTrust-4,0,100);s.forestUnease+=2;appendLog(s,"買掛の支払いは残りました。利息がつき、次の夜へ持ち越されました。");return true;});}
function applyCookieFactoryDividend(s){const total=getFactoryDividendTotal(s);if(total<=0)return;changeHand(s,total);appendLog(s,`クッキー工場から配当として${total}枚届きました。`);} 
function sellCookieFactory(){showForestToast("工場を売る話は、まだ誰にも切り出せません。");}

function getSettlementDay(s){return safeInt(s.day,0)+1;}
function collectSettlementPreview(s){const settlementDay=getSettlementDay(s);const fixedIncome=(s.lends||[]).reduce((a,i)=>a+(safeInt(i.day,0)===settlementDay?safeInt(i.amount,0):0),0)+(s.investReturns||[]).reduce((a,i)=>a+(safeInt(i.day,0)===settlementDay?safeInt(i.amount,0):0),0)+safeInt((s.cookieFactories||[]).length,0);const estimatedIncome=(s.dividendInvestments||[]).reduce((a,i)=>a+safeInt(i.dailyDividend,0),0)+(s.accountsReceivable||[]).reduce((a,i)=>a+(safeInt(i.dueDay,0)===settlementDay?safeInt(i.amount,0):0),0);const fixedExpense=(s.borrows||[]).reduce((a,i)=>a+(safeInt(i.day,0)===settlementDay?safeInt(i.amount,0):0),0)+getUpcomingSnackCost(s);const estimatedExpense=(s.accountsPayable||[]).reduce((a,i)=>a+(safeInt(i.dueDay,0)===settlementDay?safeInt(i.amount,0):0),0);return {fixedIncome:Math.max(0,fixedIncome),estimatedIncome:Math.max(0,estimatedIncome),fixedExpense:Math.max(0,fixedExpense),estimatedExpense:Math.max(0,estimatedExpense)};}
function getSettlementIncomeAmount(s){const p=collectSettlementPreview(s);return p.fixedIncome+p.estimatedIncome;}
function getSettlementExpenseAmount(s){const p=collectSettlementPreview(s);return p.fixedExpense+p.estimatedExpense;}
function getProjectedAfterSettlementCookies(s,{includeEstimated=true}={}){const hand=Math.max(0,safeInt(s.hand,0));const p=collectSettlementPreview(s);return hand+p.fixedIncome-p.fixedExpense+(includeEstimated?(p.estimatedIncome-p.estimatedExpense):0);}
function renderSettlementWarning(s){if(!dom.settlementWarningEl)return;const fixedOnly=getProjectedAfterSettlementCookies(s,{includeEstimated:false});const withEstimated=getProjectedAfterSettlementCookies(s,{includeEstimated:true});if(fixedOnly<=0){dom.settlementWarningEl.textContent="このまま一日を終えると、おやつが足りなくなります。";dom.settlementWarningEl.classList.remove("forest-warning-caution");dom.settlementWarningEl.hidden=false;return;}if(withEstimated<=0){dom.settlementWarningEl.textContent="配当や売掛が届かないと、クッキーが足りなくなるかもしれません。";dom.settlementWarningEl.classList.add("forest-warning-caution");dom.settlementWarningEl.hidden=false;return;}dom.settlementWarningEl.hidden=true;dom.settlementWarningEl.classList.remove("forest-warning-caution");}
function renderStatusStats(s){const hand=Math.max(0,safeInt(s.hand,0));const p=collectSettlementPreview(s);const snack=getDailySnackCostBreakdown(s);dom.statusEl.textContent=`手持ちクッキー: ${hand}（確定 +${p.fixedIncome}/-${p.fixedExpense}、見込み +${p.estimatedIncome}/-${p.estimatedExpense}）`;if(dom.snackCostEl)dom.snackCostEl.textContent=`今日使うクッキー: ${snack.total}枚`;if(dom.snackCostDetailEl)dom.snackCostDetailEl.textContent=`動物たちのおやつ ${snack.animalSnack}枚 + 森のざわめき ${snack.uneaseSnack}枚`;if(dom.animalsEl)dom.animalsEl.textContent=`おやつを待つ動物たち: ${getAnimalCount(s)}匹`;if(dom.upcomingNoteEl)dom.upcomingNoteEl.hidden=(p.fixedIncome+p.estimatedIncome)<=0;renderSettlementWarning(s);}
function applyFactoryEvents(s){if(!s.factoryEventsEnabled)return;s.lastFactoryEventDay=safeInt(s.day,0);}
function triggerFactoryEvent(_eventId){/* 将来の工場イベント実装用 */}
function renderFactoryStatus(s){const fc=(s.cookieFactories||[]).length;if(!dom.factorySummary)return;const reduction=safeInt(s.factoryAnimalReduction,0);const baseAnimals=getBaseAnimalsForDay(s.day);const currentAnimals=getAnimalCount(s);const effectiveReduction=Math.max(0,baseAnimals-currentAnimals);dom.factorySummary.textContent=`クッキー小屋: ${fc}軒 / 小屋の落ち着き効果: ${effectiveReduction}匹ぶん（設定値 ${reduction}） / 今のおやつ相手: ${currentAnimals}匹 / おやつ相手は最低1匹までです`;if(dom.factoryNote)dom.factoryNote.textContent=s.hand>=50?"今なら建てられます。小屋のおかげで、集まる動物が少し落ち着いています。":"50枚で建てられます。小屋の効果で動物が落ち着くと、おやつが軽くなります。";}
function getActiveDividendInvestments(s){if(Array.isArray(s.dividendInvestments))return s.dividendInvestments;const fromInvestments=Array.isArray(s.investments)?s.investments.filter((x)=>x&&x.type==="dividend_like"):[];return fromInvestments;}
function getDividendPlanByName(name){return (PLANS.invest||[]).find((plan)=>plan.type==="dividend_like"&&plan.shortLabel===name);}
function renderDividendInvestments(s){const source=getActiveDividendInvestments(s);const grouped=new Map();source.forEach((inv)=>{const key=String(inv.planId||inv.name||inv.id||"unknown");const plan=getDividendPlanByName(inv.name)||null;const prev=grouped.get(key)||{name:inv.name||"配当の話",count:0,dailyDividend:0,bankruptcyRate:safeNumber(inv.bankruptcyRate,0),detailLabel:plan?.detailLabel||""};prev.count+=1;prev.dailyDividend+=safeInt(inv.dailyDividend,0);if(plan)prev.detailLabel=plan.detailLabel||prev.detailLabel;grouped.set(key,prev);});const rows=Array.from(grouped.values()).map((x)=>{const riskLabel=x.detailLabel.includes("倒産しやすい")?"倒産しやすい":x.detailLabel.includes("倒産あり")?"倒産あり":"倒産あり";return `${x.name} ×${x.count}: 毎日 +${safeInt(x.dailyDividend,0)} / ${riskLabel}`;});renderList(dom.dividendList,rows,"配当中の話はありません。");}
function getBlackMarketInventoryCounts(s){const counts={black_cookie:0,very_tasty_cookie:0,cookie_question:0};(s.blackMarketInventory||[]).forEach((item)=>{if(item&&Object.hasOwn(counts,item.itemId))counts[item.itemId]+=1;});return counts;}
function renderBlackMarketInventorySummary(s){if(!dom.inventorySummaryEl)return;const counts=getBlackMarketInventoryCounts(s);dom.inventorySummaryEl.textContent=`夜の在庫: 黒いクッキー ${counts.black_cookie} / すごくおいしいクッキー ${counts.very_tasty_cookie} / クッキー？ ${counts.cookie_question}`;}
function getForestUnease(s){return safeInt(s&&s.forestUnease,0);}
function getBlackMarketTrust(s){return clamp(safeInt(s&&s.blackMarketTrust,50),0,100);}
function renderCoreStats(s){if(dom.uneaseEl)dom.uneaseEl.innerHTML=`森のざわめき: ${getForestUnease(s)} <small class="forest-stat-help">高いほど、おやつ代や取引条件が悪くなります。</small>`;if(dom.trustEl)dom.trustEl.innerHTML=`夜の信用: ${getBlackMarketTrust(s)} <small class="forest-stat-help">高いほど、夜の市場で少し有利になります。</small>`;if(dom.trustHelpEl&&safeInt(s.day,0)<10){dom.trustHelpEl.textContent="高いほど、夜の市場で少し有利になります。夜の市場で使われます。";}else if(dom.trustHelpEl){dom.trustHelpEl.textContent="高いほど、夜の市場で少し有利になります。";}}

function getDailyMarketOffset(itemId,tradeType,day){const seed=`${itemId}:${tradeType}:${safeInt(day,0)}`;let hash=0;for(let i=0;i<seed.length;i+=1){hash=(hash*31+seed.charCodeAt(i))>>>0;}const normalized=(hash%10000)/10000;return normalized*2-1;}
function getDailyMarketRate(item,tradeType,day){return getDailyMarketOffset(item.id,tradeType,day)*safeNumber(item&&item.dailyVolatility,0);}
function getTrustPriceMultiplier(s,item){const trustOffset=clamp((safeInt(s.blackMarketTrust,50)-50)/50,-1,1);const volatility=safeNumber(item&&item.volatility,0.10);return {payable:1-trustOffset*volatility,receivable:1+trustOffset*volatility};}
function getBlackMarketPayableAmount(item,s){const dailyRate=getDailyMarketRate(item,"payable",safeInt(s.day,0));const trust=getTrustPriceMultiplier(s,item).payable;const discount=clampRate(safeNumber(s.temporaryEffects?.blackMarketPayableDiscountToday,0),0,0.4);return Math.max(1,Math.ceil((safeInt(item.buyCost,0))*trust*(1+dailyRate)*(1-discount)));}
function getBlackMarketReceivableAmount(item,s){const dailyRate=getDailyMarketRate(item,"receivable",safeInt(s.day,0));const trust=getTrustPriceMultiplier(s,item).receivable;let bonusRate=safeNumber(s.temporaryEffects?.blackMarketReceivableBonusToday,0);if(item.id==="cookie_question")bonusRate+=safeNumber(s.temporaryEffects?.cookieQuestionReceivableBonusToday,0);return Math.max(1,Math.floor((safeInt(item.sellPrice,0))*trust*(1+dailyRate+bonusRate)));}
function getUneasePenaltyRate(s){return Math.min(0.20,safeInt(s.forestUnease,0)*0.02);}
function getAdjustedLendReturn(plan,s){return Math.max(safeInt(plan.cost,0)+1,Math.floor(safeInt(plan.returnAmount,0)*(1-getUneasePenaltyRate(s))));}
function getAdjustedBorrowRepay(plan,s){return Math.ceil(safeInt(plan.repayAmount,0)*(1+getUneasePenaltyRate(s)));}
function getAdjustedInvestCost(plan,s){return Math.ceil(safeInt(plan.cost,0)*(1+getUneasePenaltyRate(s)));}
function collectSettlementActualLog(s,beforeHand){const day=safeInt(s.day,0);const dividendIncome=(s.dividendInvestments||[]).reduce((a,i)=>a+safeInt(i.dailyDividend,0),0);const receivableIncome=(s.accountsReceivable||[]).reduce((a,i)=>a+(safeInt(i.dueDay,0)===day?safeInt(i.amount,0):0),0);const payableExpense=(s.accountsPayable||[]).reduce((a,i)=>a+(safeInt(i.dueDay,0)===day?safeInt(i.amount,0):0),0);return [{type:"before",label:"開始手持ち",amount:beforeHand},{type:"income",label:"貸付返却",amount:(s.lends||[]).reduce((a,i)=>a+(safeInt(i.day,0)===day?safeInt(i.amount,0):0),0)},{type:"income",label:"予約型投資返却",amount:(s.investReturns||[]).reduce((a,i)=>a+(safeInt(i.day,0)===day?safeInt(i.amount,0):0),0)},{type:"income",label:"配当（見込み）",amount:dividendIncome},{type:"income",label:"工場配当",amount:safeInt((s.cookieFactories||[]).length,0)},{type:"income",label:"売掛回収（見込み）",amount:receivableIncome},{type:"expense",label:"前借り返済",amount:-(s.borrows||[]).reduce((a,i)=>a+(safeInt(i.day,0)===day?safeInt(i.amount,0):0),0)},{type:"expense",label:"買掛支払い（見込み）",amount:-payableExpense},{type:"expense",label:"おやつ代",amount:-getDailySnackCost(s)}];}
function debugSettlementComparison(s,beforeHand,actualRows){const preview=collectSettlementPreview(s);const projectedFixed=beforeHand+preview.fixedIncome-preview.fixedExpense;const projectedEstimated=projectedFixed+preview.estimatedIncome-preview.estimatedExpense;const rows=[{type:"before",label:"開始手持ち",amount:beforeHand},{type:"preview",label:"確定 収入",amount:preview.fixedIncome},{type:"preview",label:"確定 支出",amount:-preview.fixedExpense},{type:"preview",label:"見込み 収入",amount:preview.estimatedIncome},{type:"preview",label:"見込み 支出",amount:-preview.estimatedExpense},{type:"preview",label:"確定のみ予測終了",amount:projectedFixed},{type:"preview",label:"見込み込み予測終了",amount:projectedEstimated},...actualRows,{type:"after",label:"終了手持ち",amount:safeInt(s.hand,0)}];console.debug("[forest-life] settlement comparison",{day:s.day});console.table(rows);} 
function beginDay(s){if(s.status!=="playing")return;const beforeHand=safeInt(s.hand,0);s.day+=1;resetTemporaryEffects(s);const actualRows=collectSettlementActualLog(s,beforeHand);s.animals=getAnimalCount(s);showForestToast(`${s.day}日目`);s.lends=s.lends.filter(i=>i.day!==s.day||(changeHand(s,i.amount),false));s.investReturns=s.investReturns.filter(i=>i.day!==s.day||(changeHand(s,i.amount),false));s.dividendInvestments=s.dividendInvestments.filter((inv)=>{const effectiveBankruptcyRate=clampRate(Number(inv.bankruptcyRate||0)+s.forestUnease*0.002,0,0.75);if(Math.random()<effectiveBankruptcyRate)return false;changeHand(s,safeInt(inv.dailyDividend,0));return true;});applyCookieFactoryDividend(s);applyAccountsReceivable(s);s.borrows=s.borrows.filter(i=>i.day!==s.day||(changeHand(s,-safeInt(i.amount,0)),false));applyAccountsPayable(s);applyFactoryEvents(s);const snackBreakdown=getDailySnackCostBreakdown(s);const snack=snackBreakdown.total;changeHand(s,-snack);s.totalSnackPaid+=snack;appendLog(s,`今日使うクッキーは${snack}枚（動物 ${snackBreakdown.animalSnack} / ざわめき ${snackBreakdown.uneaseSnack}）でした。`);recordCookieHistory(s,s.day,s.hand);const unlocks=MILESTONE_UNLOCKS[s.day]||[];if(unlocks.length){unlocks.forEach((msg)=>appendLog(s,msg));showForestToast(s.day===10?"夜の市場のうわさを聞きました":"新しい選択肢が増えました");}const dailyNet=safeInt(s.hand,0)-beforeHand;appendLog(s,`今日の流れ: 森から ${dailyNet>=0?`+${dailyNet}`:String(dailyNet)} / おやつ -${snack} / 手元 ${safeInt(s.hand,0)}枚`);appendLog(s,`おやつの内訳: 動物 ${snackBreakdown.animalSnack}枚 + ざわめき ${snackBreakdown.uneaseSnack}枚`);const dailyEvent=applyDailyEvent(s);if(dailyEvent)renderForestLife();debugSettlementComparison(s,beforeHand,actualRows);if(s.hand<=0){s.status="ended";s.tired=true;s.survivedDays=Math.max(0,s.day-1);appendLog(s,"クッキーが足りなくなってしまいました。");showForestToast("クッキーが足りなくなってしまった");return;}s.actionsLeft=Math.max(1,ACTIONS_PER_DAY+safeSignedInt(s.temporaryEffects?.actionBonusToday,0));s.tired=false;s.blackMarketUsedToday=false;}
function doWork(s){if(s.actionsLeft<=0)return;const reward=getWorkReward(s);changeHand(s,reward);appendLog(s,`森で働いて、クッキーを${reward}枚受け取りました。`);consumeAction(s);} 
function doBlackMarketBuy(s,item){if(s.actionsLeft<=0)return;const amount=getBlackMarketPayableAmount(item,s);s.accountsPayable.push({id:crypto.randomUUID(),itemId:item.id,dueDay:s.day+3,amount,interestOnFailure:2,label:item.label});s.blackMarketInventory.push({itemId:item.id,label:item.label});s.forestUnease+=safeInt(item.uneaseGainOnTrade,1);s.blackMarketTrust=clamp(s.blackMarketTrust+(item.id==="cookie_question"?-1:1),0,100);appendLog(s,`${item.label}を買掛で仕入れました。3日後に${amount}枚支払います。`);consumeAction(s);} 
function doBlackMarketSell(s,item){if(s.actionsLeft<=0)return;const idx=s.blackMarketInventory.findIndex((x)=>x.itemId===item.id);if(idx<0)return;const amount=getBlackMarketReceivableAmount(item,s);s.blackMarketInventory.splice(idx,1);s.accountsReceivable.push({id:crypto.randomUUID(),itemId:item.id,dueDay:s.day+3,amount,label:item.label});s.forestUnease+=safeInt(item.uneaseGainOnTrade,1);s.blackMarketTrust=clamp(s.blackMarketTrust+1,0,100);appendLog(s,`${item.label}を売掛で売りました。3日後に${amount}枚受け取る約束です。`);consumeAction(s);} 
function buildCookieFactory(s){if(s.hand<50)return;changeHand(s,-50);s.cookieFactories.push({id:crypto.randomUUID(),builtDay:s.day});s.reincarnationCount+=1;s.factoryAnimalReduction=safeInt(s.factoryAnimalReduction,0)+5;s.animals=getAnimalCount(s);appendLog(s,"クッキー工場を建てました。何匹かの動物たちは、そこで自分たちのおやつをまかなうようになりました。");appendLog(s,"おやつを待つ動物が5匹減りました。");showForestToast("クッキー工場を建てました");}
function openActionModal(category){selectedActionCategory=category;renderForestLife();}
function closeActionModal(){selectedActionCategory=null;renderForestLife();}
function handleActionModalClick(event){const button=event.target.closest("button");if(!button||button.disabled)return;const s=loadForestLifeState();if(button.dataset.planId){applySelectedPlan(s,button.dataset.planId);saveForestLifeState(s);closeActionModal();return;}if(button.dataset.marketItemId&&button.dataset.marketMode){const item=itemById(button.dataset.marketItemId);if(!item)return;if(button.dataset.marketMode==="buy"){doBlackMarketBuy(s,item);}else{doBlackMarketSell(s,item);}saveForestLifeState(s);closeActionModal();return;}}
function applySelectedPlan(s,planId){const category=selectedActionCategory;if(!category||!PLANS[category])return;const plan=PLANS[category].find((x)=>x.id===planId);if(!plan)return;if(s.status!=="playing"||s.actionsLeft<=0)return;if(s.day<safeInt(plan.unlockDay,1))return;
if(category==="lend"){if(s.hand<safeInt(plan.cost,0))return;const ret=getAdjustedLendReturn(plan,s);changeHand(s,-safeInt(plan.cost,0));s.lends.push({id:crypto.randomUUID(),day:s.day+safeInt(plan.dueDays,0),amount:ret});appendLog(s,`${plan.shortLabel}を選びました。${plan.dueDays}日後に${ret}枚の予定です。`);}
if(category==="borrow"){const repay=getAdjustedBorrowRepay(plan,s);changeHand(s,safeInt(plan.gain,0));s.borrows.push({id:crypto.randomUUID(),day:s.day+safeInt(plan.dueDays,0),amount:repay});appendLog(s,`${plan.shortLabel}を選びました。${plan.dueDays}日後に${repay}枚返します。`);}
if(category==="invest"){const cost=getAdjustedInvestCost(plan,s);if(s.hand<cost)return;changeHand(s,-cost);if(plan.type==="instant_risk"){if(Math.random()<getAdjustedInvestSuccessRate(plan,s)){const gain=safeInt(plan.successReturn,0);changeHand(s,gain);s.investResults.unshift(`Day${s.day}: ${plan.shortLabel}はうまくいき、${gain}枚受け取りました。`);showForestToast(`当たり。${cost}枚が${gain}枚になりました`);}else{s.investResults.unshift(`Day${s.day}: ${plan.shortLabel}は外れました。`);showForestToast(`外れ。${cost}枚は戻ってきませんでした`);}}else{s.dividendInvestments.push({id:crypto.randomUUID(),planId:plan.id,type:plan.type,name:plan.shortLabel,dailyDividend:safeInt(plan.dailyDividend,0),bankruptcyRate:safeNumber(plan.bankruptcyRate,0)});s.investResults.unshift(`Day${s.day}: ${plan.shortLabel}を始めました。`);}}s.investResults=(s.investResults||[]).slice(0,60);
consumeAction(s);
}
function renderList(el,rows,empty){if(!el)return;el.innerHTML="";if(!rows.length){const li=document.createElement("li");li.textContent=empty;el.appendChild(li);return;}rows.forEach((r)=>{const li=document.createElement("li");li.textContent=r;el.appendChild(li);});}
function renderActionModalBody(s){if(!dom.actionModalBody||!dom.actionModalTitle||!dom.actionModalDescription)return;const category=selectedActionCategory;const isOpen=Boolean(category&&(PLANS[category]||category==="blackMarket"));if(dom.actionModal)dom.actionModal.hidden=!isOpen;if(!isOpen)return;const titleMap={lend:"どこにあずけますか？",borrow:"どこから前借りしますか？",invest:"どこに森のクッキーを預けますか？",blackMarket:"夜の市場で取引しますか？"};dom.actionModalTitle.textContent=titleMap[category]||"選択してください";dom.actionModalBody.innerHTML="";if(category==="blackMarket"){BLACK_MARKET_ITEMS.forEach((item)=>{const payable=getBlackMarketPayableAmount(item,s);const receivable=getBlackMarketReceivableAmount(item,s);const buy=document.createElement("button");buy.type="button";buy.dataset.marketItemId=item.id;buy.dataset.marketMode="buy";buy.textContent=`${item.label}を買掛で仕入れる 在庫 +1 / 3日後 -${payable}`;buy.disabled=s.actionsLeft<=0||s.status!=="playing";dom.actionModalBody.appendChild(buy);const sell=document.createElement("button");sell.type="button";sell.dataset.marketItemId=item.id;sell.dataset.marketMode="sell";sell.textContent=`${item.label}を売掛で売る 在庫 -1 / 3日後 +${receivable}`;sell.disabled=s.actionsLeft<=0||s.status!=="playing"||!s.blackMarketInventory.some((x)=>x.itemId===item.id);dom.actionModalBody.appendChild(sell);});return;}const plans=(PLANS[category]||[]);if(!plans.length){const p=document.createElement("p");p.textContent="まだ選べる話がありません。";dom.actionModalBody.appendChild(p);return;}plans.forEach((plan)=>{const button=document.createElement("button");button.type="button";button.dataset.planId=plan.id;if(category==="lend"){button.textContent=`${plan.shortLabel} -${plan.cost} / ${plan.dueDays}日後 +${getAdjustedLendReturn(plan,s)}`;}else if(category==="borrow"){button.textContent=`${plan.shortLabel} +${plan.gain} / ${plan.dueDays}日後 -${getAdjustedBorrowRepay(plan,s)}`;}else if(category==="invest"){button.textContent=plan.type==="instant_risk"?`${plan.shortLabel} -${getAdjustedInvestCost(plan,s)} / ${Math.round(getAdjustedInvestSuccessRate(plan,s)*100)}%で +${plan.successReturn}`:`${plan.shortLabel} -${getAdjustedInvestCost(plan,s)} / 毎日 +${plan.dailyDividend}`;}const unlockDay=safeInt(plan.unlockDay,1);const cost=safeInt(plan.cost,0);const missing=Math.max(0,cost-safeInt(s.hand,0));const reasons=[];if(s.day<unlockDay){reasons.push(`まだ森がその準備をしていません（${unlockDay}日目から選べます）`);}if(category!=="borrow"&&missing>0){reasons.push(`クッキーがあと${missing}枚必要です`);}if(s.actionsLeft<=0){reasons.push("今日はもう動けません");}if(s.status!=="playing"){reasons.push("今はこの行動を選べません");}button.disabled=reasons.length>0;button.setAttribute("aria-disabled",button.disabled?"true":"false");if(button.disabled){button.title=reasons.join(" / ");}dom.actionModalBody.appendChild(button);const detail=document.createElement("p");detail.className="forest-plan-help";detail.textContent=reasons.length?`選べない理由: ${reasons.join(" / ")}`:`条件OK: ${unlockDay}日目から・必要クッキー ${cost}枚`;dom.actionModalBody.appendChild(detail);});}
function renderBlackMarketPanel(s){if(!dom.blackMarketPanel)return;dom.blackMarketPanel.hidden=s.day<10||s.status!=="playing"||selectedActionCategory!=="blackMarket";if(dom.modalTrustEl)dom.modalTrustEl.textContent=`現在の夜の信用: ${getBlackMarketTrust(s)}`;renderList(dom.inventoryList,s.blackMarketInventory.map((x)=>x.label),"夜の在庫はまだありません。");renderList(dom.arList,s.accountsReceivable.map((x)=>`${x.label}: ${x.dueDay}日目に${x.amount}枚`),"受け取る約束はありません。");renderList(dom.apList,s.accountsPayable.map((x)=>`${x.label}: ${x.dueDay}日目に${x.amount}枚`),"支払う約束はありません。");dom.blackMarketActions.innerHTML="";BLACK_MARKET_ITEMS.forEach((item)=>{const mk=(label,fn)=>{const b=document.createElement("button");b.type="button";b.textContent=label;b.disabled=s.actionsLeft<=0;b.onclick=()=>{const st=loadForestLifeState();fn(st);saveForestLifeState(st);renderForestLife();};dom.blackMarketActions.appendChild(b);return b;};const pay=getBlackMarketPayableAmount(item,s);const rec=getBlackMarketReceivableAmount(item,s);mk(`${item.label}を買掛で仕入れる 在庫+1 / 3日後-${pay}`,(st)=>doBlackMarketBuy(st,item));const hasStock=s.blackMarketInventory.some((x)=>x.itemId===item.id);const sellBtn=mk(`${item.label}を売掛で売る 在庫-1 / 3日後+${rec}`,(st)=>doBlackMarketSell(st,item));sellBtn.disabled=s.actionsLeft<=0||!hasStock;});}

function getOutstandingLendingReturnTotal(s){return Math.max(0,safeInt((s.lends||[]).reduce((a,b)=>a+safeInt(b.amount,0),0),0));}
function getOutstandingBorrowRepayTotal(s){return Math.max(0,safeInt((s.borrows||[]).reduce((a,b)=>a+safeInt(b.amount,0),0),0));}
function calculateReturnToStorageBreakdown(s){const hand=Math.max(0,safeInt(s?.hand,0));const lendingReturns=getOutstandingLendingReturnTotal(s);const borrowRepayments=getOutstandingBorrowRepayTotal(s);const totalBeforeClamp=hand+lendingReturns-borrowRepayments;return {hand,lendingReturns,borrowRepayments,totalBeforeClamp,returnedToStorage:Math.max(0,safeInt(totalBeforeClamp,0))};}
function normalizeCookieHistory(history){const src=Array.isArray(history)?history:[];const map=new Map();src.forEach((row)=>{const day=Number(row?.day);if(!Number.isFinite(day))return;const normalizedDay=Math.floor(day);if(normalizedDay<1)return;const handRaw=Number(row?.hand);const normalizedHand=Number.isFinite(handRaw)?Math.max(0,Math.floor(handRaw)):0;map.set(normalizedDay,{day:normalizedDay,hand:normalizedHand});});return Array.from(map.values()).sort((a,b)=>a.day-b.day);}
function getCookieHistory(s){const normalized=normalizeCookieHistory(s?.cookieHistory);if(s)s.cookieHistory=normalized;return normalized;}
function recordCookieHistory(s,day=s?.day,hand=s?.hand){if(!s)return;const history=getCookieHistory(s);const d=Number(day);if(!Number.isFinite(d))return;const normalizedDay=Math.floor(d);if(normalizedDay<1)return;const handRaw=Number(hand);const normalizedHand=Number.isFinite(handRaw)?Math.max(0,Math.floor(handRaw)):0;const idx=history.findIndex((x)=>x.day===normalizedDay);if(idx>=0)history[idx]={day:normalizedDay,hand:normalizedHand};else history.push({day:normalizedDay,hand:normalizedHand});s.cookieHistory=normalizeCookieHistory(history);}
function buildCookieHistorySvg(history){if(!Array.isArray(history)||history.length<2)return "";const w=320,h=160,m={l:34,r:12,t:10,b:24};const minDay=Math.min(...history.map((x)=>x.day));const maxDay=Math.max(...history.map((x)=>x.day));const maxHand=Math.max(...history.map((x)=>Math.max(0,safeInt(x.hand,0))),0);const daySpan=Math.max(1,maxDay-minDay);const yMax=Math.max(1,maxHand);const toX=(d)=>m.l+((d-minDay)/daySpan)*(w-m.l-m.r);const toY=(v)=>h-m.b-(Math.max(0,safeInt(v,0))/yMax)*(h-m.t-m.b);const pts=history.map((x)=>`${toX(x.day).toFixed(2)},${toY(x.hand).toFixed(2)}`).join(" ");const dots=history.map((x)=>`<circle cx="${toX(x.day).toFixed(2)}" cy="${toY(x.hand).toFixed(2)}" r="2.4"/>`).join("");return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="日数ごとのクッキー枚数推移"><line x1="${m.l}" y1="${m.t}" x2="${m.l}" y2="${h-m.b}" class="axis"/><line x1="${m.l}" y1="${h-m.b}" x2="${w-m.r}" y2="${h-m.b}" class="axis"/><polyline points="${pts}" class="line"/>${dots}<text x="${m.l}" y="${h-6}" class="label">${minDay}日目</text><text x="${w-m.r}" y="${h-6}" text-anchor="end" class="label">${maxDay}日目</text><text x="${m.l+2}" y="${m.t+10}" class="label">${maxHand}枚</text><text x="${m.l+2}" y="${h-m.b-2}" class="label">0枚</text></svg>`;}
function renderCookieHistoryChart(s){if(!dom.cookieHistoryChart)return;const history=getCookieHistory(s);if(history.length<2){dom.cookieHistoryChart.innerHTML='<p class="forest-chart-empty">まだ推移を描けるほどの記録がありません。</p>';return;}dom.cookieHistoryChart.innerHTML=buildCookieHistorySvg(history);}
function getForestLifeSummaryText(history,s){const h=(Array.isArray(history)&&history.length?history:[{day:1,hand:Math.max(0,safeInt(s?.hand,0))}]).map((x)=>Math.max(0,safeInt(x.hand,0)));const first=h[0]||0,last=h[h.length-1]||0;const delta=last-first;const min=Math.min(...h,0);const swings=h.slice(1).reduce((a,v,i)=>a+Math.abs(v-h[i]),0);const volatile=swings>Math.max(10,Math.abs(delta)*2);let msg='森の暮らしは、日ごとに表情を変えながら続いていきました。';if(delta>=8&&!volatile)msg='森の暮らしは、少しずつ根を張るように育っていきました。おやつの袋は、日を追うごとに重くなっていきました。';else if(delta>=8&&volatile)msg='森の暮らしは、静かな日ばかりではありませんでした。袋は重くなったり軽くなったりしながら、それでも夜明けを越えていきました。';else if(delta<=-5&&last<=first)msg='森の暮らしは、少しずつ袋の底が見えていく日々でした。それでも、あなたはできるだけ長くおやつをまかない続けました。';else if(h.length>=3&&h[h.length-1]>h[h.length-2]&&min<=Math.floor(first*0.5))msg='終わりが近いように見えた日もありました。けれど森のどこかで、まだ明日のぶんのおやつが見つかりました。';if(safeInt(s?.forestUnease,0)>=18)msg+=' 森の奥のざわめきは、最後まで消えませんでした。';if(safeInt((s?.cookieFactories||[]).length,0)>0)msg+=' クッキー工場の灯りは、森の暮らしを少しだけ支えていました。';if(s?.retired)msg+=' あなたは、残ったクッキーを抱えて森を出ました。';return msg;}

function renderForestLife(){const s=loadForestLifeState();const balance=loadCookieBalance();dom.balanceEl.textContent=`現在のフォレストクッキー: ${balance}枚`;if(dom.addBroughtInButton)dom.addBroughtInButton.disabled=balance<=0;dom.startScreen.hidden=s.status!=="idle";dom.gameScreen.hidden=s.status!=="playing";dom.resultScreen.hidden=s.status!=="ended";if(s.status==="idle"){const maxBroughtIn=balance;const currentInput=safeInt(dom.broughtInInput.value,0);dom.broughtInInput.max=String(maxBroughtIn);dom.broughtInInput.value=String(clamp(currentInput,0,maxBroughtIn));const hasBalance=balance>0;dom.startButton.disabled=!hasBalance||safeInt(dom.broughtInInput.value,0)<=0;dom.broughtInInput.disabled=!hasBalance;if(dom.emptyNoteEl)dom.emptyNoteEl.hidden=hasBalance;}if(s.status==="playing"){s.animals=getAnimalCount(s);dom.dayEl.textContent=`現在の日数: ${s.day}日目`;renderStatusStats(s);renderCoreStats(s);renderBlackMarketInventorySummary(s);renderFactoryStatus(s);dom.factoryButton.disabled=!(s.status==="playing"&&s.hand>=50);dom.actionsLeftEl.textContent=`今日の残り行動回数: ${s.actionsLeft}回`;dom.dayStatusEl.textContent=s.actionsLeft===0?"今日はもうくたくたです。明日にしましょう。":"森は静かです。次の行動を選んでください。";const canAct=s.actionsLeft>0&&s.status==="playing";dom.workButton.disabled=!canAct;dom.lendButton.disabled=!canAct;dom.borrowButton.disabled=!canAct;dom.investButton.disabled=!canAct;if(dom.investDisabledReasonEl){if(s.status!=="playing")dom.investDisabledReasonEl.textContent="今は森に預ける行動を選べません。";else if(s.actionsLeft<=0)dom.investDisabledReasonEl.textContent="今日はもう動けません。明日になるとまた選べます。";else dom.investDisabledReasonEl.textContent="森に預ける行動は、日数や手持ちクッキーが足りると選べます。押すと、選べる預け先が表示されます。";dom.investDisabledReasonEl.hidden=false;}dom.blackMarketHint.hidden=s.day<10;dom.blackMarketButton.hidden=s.day<10;dom.blackMarketButton.disabled=!canAct;dom.blackMarketButton.textContent=s.day>=10?"夜の市場を開く（闇市商人）":"夜の市場をのぞく（まだ入れない）";renderBlackMarketPanel(s);renderActionModalBody(s);if(dom.retireButton)dom.retireButton.hidden=!(s.day>=20&&!s.retired);dom.nextDayButton.disabled=!s.tired;renderList(dom.lendList,s.lends.map((x)=>`${x.day}日目に ${x.amount}枚 返却予定`),"予約中の貸付はありません。");renderList(dom.borrowList,s.borrows.map((x)=>`${x.day}日目に ${x.amount}枚 返済予定`),"返済予定の借り入れはありません。");renderDividendInvestments(s);renderList(dom.investLog,s.investResults||[],"投資ログはまだありません。");renderList(dom.actionLog,s.actionLogs||[],"行動ログはまだありません。");renderList(dom.forestEventsLog,(s.eventLog||[]).map((entry)=>{const e=normalizeEventLogEntry(entry,s.day);const effectText=e.effects.length?` 効果: ${e.effects.join(" / ")}`:"";return `${safeInt(e.day,0)}日目: ${e.title} / ${e.description}${effectText}`;}),"まだ大きなできごとはありません。");}
if(s.status==="ended"){const survivedDays=safeInt(s.survivedDays,s.day);if(dom.affiliateLink)dom.affiliateLink.href=FOREST_AFFILIATE_LINK;dom.resultTitle.textContent=`森で${survivedDays}日分のおやつをまかなえました`;dom.resultBroughtIn.textContent=`持ち込んだクッキー数: ${s.broughtIn}`;dom.resultDay.textContent=`最終日数: ${s.day}`;const lendingTotal=getOutstandingLendingReturnTotal(s);const borrowingTotal=getOutstandingBorrowRepayTotal(s);dom.resultBalance.textContent=`最後の手持ちクッキー: ${Math.max(0,safeInt(s.hand,0))}`;dom.resultLending.textContent=`貸付中だったクッキー数: ${lendingTotal}`;dom.resultBorrowing.textContent=`返済予定だったクッキー数: ${borrowingTotal}`;dom.resultDay.textContent+=s.retired?" / 森の暮らしは、ここで一区切りです。":" / クッキーが足りなくなってしまいました。";const breakdown=s.returnBreakdown&&typeof s.returnBreakdown==="object"?s.returnBreakdown:calculateReturnToStorageBreakdown(s);if(dom.returnBreakdownWrap)dom.returnBreakdownWrap.hidden=!s.retired;if(dom.returnBreakdownBody&&s.retired){const fmt=(n)=>safeInt(n,0);dom.returnBreakdownBody.innerHTML=`<tr><td>手持ちのクッキー</td><td>+${fmt(breakdown.hand)}</td></tr><tr><td>貸付中だったクッキー</td><td>+${fmt(breakdown.lendingReturns)}</td></tr><tr><td>返済予定だったクッキー</td><td>-${fmt(breakdown.borrowRepayments)}</td></tr><tr><th>持ち帰りクッキー</th><th>${fmt(breakdown.returnedToStorage)}</th></tr>`;}if(s.retired){dom.resultBalance.textContent=`持ち帰りクッキー: ${safeInt(s.returnedCookies,0)}枚`;dom.resultLending.hidden=true;dom.resultBorrowing.hidden=true;}else{dom.resultLending.hidden=false;dom.resultBorrowing.hidden=false;}renderCookieHistoryChart(s);if(dom.lifeSummaryText)dom.lifeSummaryText.textContent=getForestLifeSummaryText(getCookieHistory(s),s);}}
function startForestLifeGame(){const bal=loadCookieBalance(),inb=safeInt(dom.broughtInInput.value,0);if(inb<=0||inb>bal)return;const s=newState();s.status="playing";s.broughtIn=inb;s.hand=0;changeHand(s,inb,{silentSound:true});addCookieBalance(-inb);beginDay(s);recordCookieHistory(s,s.day,s.hand);saveForestLifeState(s);tryPlayBgm();renderForestLife();}
